class Account { public balance: number; }
class AccountServiceA {
  private acct = new Account();
  getAccount(): Account { return this.acct; }
}

// Version B
class AccountSnapshot { constructor(public readonly balance: number) {} }
class AccountServiceB {
  private acct = new Account();
  deposit(amount: number) { this.acct.balance += amount; }
  getSnapshot(): AccountSnapshot { return new AccountSnapshot(this.acct.balance); }
}
